DELIMITER $$
--
-- Procedures
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `CariPelanggan` (IN `p_id` INT)   BEGIN
    SELECT *
    FROM pelanggan
    WHERE id_pelanggan = p_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `HitungPelanggan` (OUT `jumlah` INT)   BEGIN
    SELECT COUNT(*)
    INTO jumlah
    FROM pelanggan;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `LaporanTransaksi` (IN `p_id` INT)   BEGIN
    SELECT
        pelanggan.id_pelanggan,
        pelanggan.nama_pelanggan,
        transaksi.id_transaksi,
        transaksi.tanggal_transaksi,
        transaksi.nama_barang,
        transaksi.jumlah,
        transaksi.harga,
        transaksi.total
    FROM pelanggan
    INNER JOIN transaksi
    ON pelanggan.id_pelanggan = transaksi.id_pelanggan
    WHERE pelanggan.id_pelanggan = p_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `TambahPelanggan` (IN `p_nama` VARCHAR(100), IN `p_kota` VARCHAR(150))   BEGIN
    INSERT INTO pelanggan
    (nama_pelanggan, alamat)
    VALUES
    (p_nama, p_kota);
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `TampilPelanggan` ()   BEGIN
    SELECT * FROM pelanggan;
END$$

--
-- Functions
--
CREATE DEFINER=`root`@`localhost` FUNCTION `HitungDiskon` (`harga` DECIMAL(12,2), `diskon` DECIMAL(5,2)) RETURNS DECIMAL(12,2) DETERMINISTIC BEGIN
    RETURN harga - (harga * diskon / 100);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `HitungPajak` (`harga` DECIMAL(12,2)) RETURNS DECIMAL(12,2) DETERMINISTIC BEGIN
    RETURN harga * 0.11;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `HitungTotal` (`harga` DECIMAL(12,2), `jumlah` INT) RETURNS DECIMAL(12,2) DETERMINISTIC BEGIN
    RETURN harga * jumlah;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `KategoriBelanja` (`total` DECIMAL(12,2)) RETURNS VARCHAR(20) CHARSET utf8mb4 COLLATE utf8mb4_general_ci DETERMINISTIC BEGIN
    IF total >= 1000000 THEN
        RETURN 'Besar';
    ELSEIF total >= 500000 THEN
        RETURN 'Menengah';
    ELSE
        RETURN 'Kecil';
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `KonversiNilai` (`nilai` INT) RETURNS CHAR(1) CHARSET utf8mb4 COLLATE utf8mb4_general_ci DETERMINISTIC BEGIN
    IF nilai >= 85 AND nilai <= 100 THEN
        RETURN 'A';
    ELSEIF nilai >= 75 THEN
        RETURN 'B';
    ELSEIF nilai >= 65 THEN
        RETURN 'C';
    ELSEIF nilai >= 50 THEN
        RETURN 'D';
    ELSE
        RETURN 'E';
    END IF;
END$$

DELIMITER ;

