--
-- Structure for view `view_laporan_transaksi`
--
DROP TABLE IF EXISTS `view_laporan_transaksi`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_laporan_transaksi`  AS SELECT `transaksi`.`id_transaksi` AS `id_transaksi`, `pelanggan`.`id_pelanggan` AS `id_pelanggan`, `pelanggan`.`nama_pelanggan` AS `nama_pelanggan`, `transaksi`.`tanggal_transaksi` AS `tanggal_transaksi`, `transaksi`.`nama_barang` AS `nama_barang`, `transaksi`.`jumlah` AS `jumlah`, `transaksi`.`harga` AS `harga`, `transaksi`.`total` AS `total` FROM (`transaksi` join `pelanggan` on(`transaksi`.`id_pelanggan` = `pelanggan`.`id_pelanggan`)) ;

-- --------------------------------------------------------

--
-- Structure for view `view_total_belanja_pelanggan`
--
DROP TABLE IF EXISTS `view_total_belanja_pelanggan`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `view_total_belanja_pelanggan`  AS SELECT `pelanggan`.`id_pelanggan` AS `id_pelanggan`, `pelanggan`.`nama_pelanggan` AS `nama_pelanggan`, count(`transaksi`.`id_transaksi`) AS `jumlah_transaksi`, coalesce(sum(`transaksi`.`total`),0) AS `total_belanja` FROM (`pelanggan` left join `transaksi` on(`pelanggan`.`id_pelanggan` = `transaksi`.`id_pelanggan`)) GROUP BY `pelanggan`.`id_pelanggan`, `pelanggan`.`nama_pelanggan` ;

